import attr
from typing import List, Optional

from .system_module import SystemModule
from .airscale import CommonUnit


@attr.s(cmp=False)
class Flexi(SystemModule):
    """

    :param List[CommonUnit] common_units: List of CommonUnit class instance objects
    :param Optional[str] product_code: product code of Flexi
    """
    common_units = attr.ib(type=List[CommonUnit])
    product_code = attr.ib(default=None, type=Optional[str])
